"""Emit Python source from a Daad AST."""
from __future__ import annotations

from . import ast_nodes as ast


PRELUDE = """\
# تم توليده بواسطة daad (ضاد) — لا تُعدّله يدوياً
# Generated by daad — do not edit by hand

# بدائل عربية للدوال المدمجة
اطبع = print
مدى = range
طول = len
نص = str
عدد = int
عشري = float
قائمة = list
قاموس = dict
مدخل = input
"""


def emit_module(module: ast.Module) -> str:
    lines = [PRELUDE]
    for stmt in module.body:
        lines.extend(emit_stmt(stmt, 0))
    lines.append("")
    return "\n".join(lines)


def emit_block(body: list[ast.Statement], indent: int) -> list[str]:
    if not body:
        return ["    " * indent + "pass"]
    out: list[str] = []
    for s in body:
        out.extend(emit_stmt(s, indent))
    return out


def emit_stmt(stmt: ast.Statement, indent: int) -> list[str]:
    pad = "    " * indent

    if isinstance(stmt, ast.FunctionDef):
        params = ", ".join(stmt.params)
        return [f"{pad}def {stmt.name}({params}):"] + emit_block(stmt.body, indent + 1)

    if isinstance(stmt, ast.ClassDef):
        bases = f"({', '.join(stmt.bases)})" if stmt.bases else ""
        return [f"{pad}class {stmt.name}{bases}:"] + emit_block(stmt.body, indent + 1)

    if isinstance(stmt, ast.If):
        out = [f"{pad}if {emit_expr(stmt.test)}:"]
        out.extend(emit_block(stmt.body, indent + 1))
        if stmt.orelse:
            if len(stmt.orelse) == 1 and isinstance(stmt.orelse[0], ast.If):
                # elif chain: emit as "else:" + nested if
                out.append(f"{pad}else:")
                out.extend(emit_stmt(stmt.orelse[0], indent + 1))
            else:
                out.append(f"{pad}else:")
                out.extend(emit_block(stmt.orelse, indent + 1))
        return out

    if isinstance(stmt, ast.For):
        return [f"{pad}for {stmt.target} in {emit_expr(stmt.iter)}:"] + emit_block(stmt.body, indent + 1)

    if isinstance(stmt, ast.While):
        return [f"{pad}while {emit_expr(stmt.test)}:"] + emit_block(stmt.body, indent + 1)

    if isinstance(stmt, ast.Return):
        return [f"{pad}return"] if stmt.value is None else [f"{pad}return {emit_expr(stmt.value)}"]

    if isinstance(stmt, ast.Assign):
        return [f"{pad}{stmt.target} = {emit_expr(stmt.value)}"]

    if isinstance(stmt, ast.AugAssign):
        return [f"{pad}{stmt.target} {stmt.op}= {emit_expr(stmt.value)}"]

    if isinstance(stmt, ast.ExprStmt):
        return [f"{pad}{emit_expr(stmt.value)}"]

    if isinstance(stmt, ast.Pass):
        return [f"{pad}pass"]

    if isinstance(stmt, ast.Break):
        return [f"{pad}break"]

    if isinstance(stmt, ast.Continue):
        return [f"{pad}continue"]

    if isinstance(stmt, ast.Import):
        return [f"{pad}import {stmt.module} as {stmt.alias}"] if stmt.alias else [f"{pad}import {stmt.module}"]

    if isinstance(stmt, ast.ImportFrom):
        return [f"{pad}from {stmt.module} import {', '.join(stmt.names)}"]

    raise TypeError(f"unknown statement: {type(stmt).__name__}")


def emit_expr(expr: ast.Expression) -> str:
    if isinstance(expr, ast.Name):
        return expr.id
    if isinstance(expr, ast.Number):
        return expr.value
    if isinstance(expr, ast.Str):
        return expr.value
    if isinstance(expr, ast.Bool):
        return "True" if expr.value else "False"
    if isinstance(expr, ast.NoneLit):
        return "None"
    if isinstance(expr, ast.BinOp):
        return f"({emit_expr(expr.left)} {expr.op} {emit_expr(expr.right)})"
    if isinstance(expr, ast.UnaryOp):
        return f"(not {emit_expr(expr.operand)})" if expr.op == "not" else f"({expr.op}{emit_expr(expr.operand)})"
    if isinstance(expr, ast.Call):
        return f"{emit_expr(expr.func)}({', '.join(emit_expr(a) for a in expr.args)})"
    if isinstance(expr, ast.Attribute):
        return f"{emit_expr(expr.value)}.{expr.attr}"
    if isinstance(expr, ast.Subscript):
        return f"{emit_expr(expr.value)}[{emit_expr(expr.index)}]"
    if isinstance(expr, ast.ListLit):
        return f"[{', '.join(emit_expr(e) for e in expr.elements)}]"
    if isinstance(expr, ast.TupleLit):
        elems = [emit_expr(e) for e in expr.elements]
        return f"({elems[0]},)" if len(elems) == 1 else f"({', '.join(elems)})"
    if isinstance(expr, ast.DictLit):
        pairs = [f"{emit_expr(k)}: {emit_expr(v)}" for k, v in zip(expr.keys, expr.values)]
        return f"{{{', '.join(pairs)}}}"
    raise TypeError(f"unknown expression: {type(expr).__name__}")
